CREATE TABLE public.communication_sandbox_accounts(user_id uuid PRIMARY KEY, tier text NOT NULL CHECK(tier IN ('paid','free')), expires_at timestamptz NOT NULL DEFAULT (now()+interval '30 days'));
GRANT SELECT ON public.communication_sandbox_accounts TO authenticated;
GRANT ALL ON public.communication_sandbox_accounts TO service_role;
ALTER TABLE public.communication_sandbox_accounts ENABLE ROW LEVEL SECURITY;
CREATE POLICY sandbox_self ON public.communication_sandbox_accounts FOR SELECT TO authenticated USING(user_id=auth.uid());
CREATE FUNCTION public.sandbox_communication_tier(account_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT tier FROM public.communication_sandbox_accounts WHERE user_id=account_id AND expires_at>now() $$;
REVOKE ALL ON FUNCTION public.sandbox_communication_tier(uuid) FROM PUBLIC,anon,authenticated;
GRANT EXECUTE ON FUNCTION public.sandbox_communication_tier(uuid) TO service_role;
CREATE OR REPLACE FUNCTION public.private_message_paid_until(account_id uuid) RETURNS timestamptz LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT CASE WHEN public.sandbox_communication_tier(account_id)='paid' THEN (SELECT expires_at FROM public.communication_sandbox_accounts WHERE user_id=account_id) ELSE (SELECT paid_until FROM public.private_message_plans WHERE user_id=account_id AND paid_until>now()) END $$;
CREATE OR REPLACE FUNCTION public.protect_private_mailbox_identity() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.trial_started_at:=CASE WHEN public.sandbox_communication_tier(NEW.user_id) IS NOT NULL THEN now()-interval '8 days' ELSE now() END; NEW.created_at:=now();NEW.mailbox_id:=gen_random_uuid(); ELSE IF NEW.trial_started_at IS DISTINCT FROM OLD.trial_started_at OR NEW.public_key IS DISTINCT FROM OLD.public_key OR NEW.mailbox_id IS DISTINCT FROM OLD.mailbox_id OR NEW.user_id IS DISTINCT FROM OLD.user_id THEN RAISE EXCEPTION 'Mailbox identity cannot be changed'; END IF; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.isolate_sandbox_messages() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF EXISTS(SELECT 1 FROM public.communication_sandbox_accounts WHERE user_id IN(NEW.sender_id,NEW.recipient_id)) AND (public.sandbox_communication_tier(NEW.sender_id) IS NULL OR public.sandbox_communication_tier(NEW.recipient_id) IS NULL) THEN RAISE EXCEPTION 'Sandbox messages can only reach active sandbox accounts'; END IF;RETURN NEW;END $$;
CREATE TRIGGER isolate_sandbox_messages BEFORE INSERT ON public.private_message_envelopes FOR EACH ROW EXECUTE FUNCTION public.isolate_sandbox_messages();
CREATE TABLE public.private_message_delivery_status(message_id uuid PRIMARY KEY,sender_id uuid NOT NULL,recipient_id uuid NOT NULL,delivered_at timestamptz NOT NULL DEFAULT now(),received_at timestamptz,replied_at timestamptz,expires_at timestamptz NOT NULL DEFAULT(now()+interval '24 hours'));
GRANT SELECT ON public.private_message_delivery_status TO authenticated;
GRANT ALL ON public.private_message_delivery_status TO service_role;
ALTER TABLE public.private_message_delivery_status ENABLE ROW LEVEL SECURITY;
CREATE POLICY sender_delivery_status ON public.private_message_delivery_status FOR SELECT TO authenticated USING(sender_id=auth.uid() AND expires_at>now());
COMMENT ON TABLE public.private_message_delivery_status IS 'Content-free temporary delivery and response metadata, visible for 24 hours; never contains message text or encryption keys.';
CREATE FUNCTION public.track_private_message_delivery() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN DELETE FROM public.private_message_delivery_status WHERE expires_at<=now(); INSERT INTO public.private_message_delivery_status(message_id,sender_id,recipient_id) VALUES(NEW.id,NEW.sender_id,NEW.recipient_id); UPDATE public.private_message_delivery_status SET replied_at=now() WHERE sender_id=NEW.recipient_id AND recipient_id=NEW.sender_id AND received_at IS NOT NULL AND replied_at IS NULL AND expires_at>now();RETURN NEW;END $$;
CREATE TRIGGER track_private_message_delivery AFTER INSERT ON public.private_message_envelopes FOR EACH ROW EXECUTE FUNCTION public.track_private_message_delivery();
CREATE FUNCTION public.acknowledge_private_inbox() RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Authentication required'; END IF; UPDATE public.private_message_delivery_status s SET received_at=coalesce(s.received_at,now()) WHERE s.recipient_id=auth.uid() AND s.expires_at>now() AND EXISTS(SELECT 1 FROM public.private_message_envelopes e WHERE e.id=s.message_id AND e.recipient_id=auth.uid() AND e.expires_at>now());END $$;
REVOKE ALL ON FUNCTION public.acknowledge_private_inbox() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.acknowledge_private_inbox() TO authenticated;